// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amount) public {
        amount = bound(amount, 0, 1 ether);

        vm.deal(actor, amount);

        uint256 beforeContractBal = address(c).balance;

        vm.prank(actor);
        c.addToBalance{value: amount}();

        uint256 stored = c.getBalance(actor);
        uint256 afterContractBal = address(c).balance;

        assertTrue(afterContractBal == beforeContractBal + amount && stored == amount);
    }
}
